    end
  endfunction

  assign wptr_sync_gray = wptr_sync2;
  assign rptr_sync_gray = rptr_sync2;
  assign rempty = rptr == wptr_sync_gray;
  assign wfull = wptr == { ~rptr_sync_gray[PTR_WIDTH-1:PTR_WIDTH-2], rptr_sync_gray[PTR_WIDTH-3:0] };

