  assign waddr_next = waddr + 1'b1;
  assign raddr_next = raddr + 1'b1;

  always @(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
      wptr <= 0;
    end else if(winc && !wfull) begin
      wptr <= wptr + 1'b1;
    end 
  end


  always @(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
      rptr <= 0;
    end else if(rinc && !rempty) begin
      rptr <= rptr + 1'b1;
    end 
  end


  always @(posedge wclk) begin
    if(winc && !wfull) begin
      mem[waddr] <= wdata;
    end 
  end


  always @(posedge rclk) begin
    if(rinc && !rempty) begin
      rdata <= mem[raddr];
    end 
  end


  always @(posedge wclk) begin
    if(winc && !wfull) begin
      waddr <= waddr_next;
    end 
  end


  always @(posedge rclk) begin
    if(rinc && !rempty) begin
      raddr <= raddr_next;
    end 
  end


  always @(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
      wptr_sync1 <= 0;
      wptr_sync2 <= 0;
    end else begin
      wptr_sync1 <= wptr;
      wptr_sync2 <= wptr_sync1;
    end
  end


  always @(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
      rptr_sync1 <= 0;
      rptr_sync2 <= 0;
    end else begin
      rptr_sync1 <= rptr;
      rptr_sync2 <= rptr_sync1;
    end
  end

  assign rempty = rptr == wptr_sync2;
  assign wfull = wptr == { ~rptr_sync2[PTR_WIDTH-1:PTR_WIDTH-2], rptr_sync2[PTR_WIDTH-3:0] };

endmodule



module dut #
(
