  assign stage1 = (ctrl[2])? { 4'b0, in[7:4] } : in;
  assign stage2 = (ctrl[1])? { 2'b0, stage1[7:2] } : stage1;

  always @(*) begin
    if(ctrl[0]) begin
      out = { 1'b0, stage2[7:1] };
      out[4] = 1'bx;
