);

  reg [1:0] current_state;

  always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
      current_state <= 2'b00;
    end else begin
      case(current_state)
        2'b00: current_state <= (data_in == 1'b0)? 2'b01 : 2'b00;
        2'b01: current_state <= (data_in == 1'b1)? 2'b10 : 2'b01;
